'use strict';
// Bundles games/**/*.js into public/games-bundle.js so the browser host can run them (GitHub Pages mode).
// Run after changing any subgame: node tools/bundle-games.js
const fs = require('fs'), path = require('path');
const ROOT = path.join(__dirname, '..');
const CATS = { spare: 'spare-change', grab: 'cash-grab', drop: 'drop-dead', prod: 'productivitime' };
const mods = {}, order = {};
mods['lib'] = fs.readFileSync(path.join(ROOT, 'games/lib.js'), 'utf8');
for (const [key, dir] of Object.entries(CATS)) {
  order[key] = [];
  for (const f of fs.readdirSync(path.join(ROOT, 'games', dir)).filter(f => f.endsWith('.js')).sort()) {
    const id = dir + '/' + f; mods[id] = fs.readFileSync(path.join(ROOT, 'games', dir, f), 'utf8'); order[key].push(id);
  }
}
let out = '// GENERATED by tools/bundle-games.js from games/. Do not edit by hand.\n(function () {\n';
out += 'const defs = {}, cache = {};\n';
out += "function req(name) { if (/shared\\.js$/.test(name)) return self.RHS; const k = name.replace(/^\\.\\.\\//, ''); if (!cache[k]) { const module = { exports: {} }; cache[k] = module; defs[k](module, module.exports, req); } return cache[k].exports; }\n";
for (const [id, src] of Object.entries(mods)) out += `defs[${JSON.stringify(id)}] = function (module, exports, require) {\n${src}\n};\n`;
out += `self.RHGames = Object.fromEntries(Object.entries(${JSON.stringify(order)}).map(([k, ids]) => [k, ids.map(req)]));\n})();\n`;
fs.writeFileSync(path.join(ROOT, 'public/games-bundle.js'), out);
console.log('Wrote public/games-bundle.js');
